namespace LSE.AutoCADElectrical.ProjectEnvironment;
public static class EnvironmentService {
 public static ProjectState ReadProject(string wdpPath,EnvRules r,HostBridge bridge,bool inspectDrawings,Action<string>? progress=null){
  if(!File.Exists(wdpPath))throw new FileNotFoundException("Project file was not found.",wdpPath);wdpPath=Path.GetFullPath(wdpPath);
  var st=new ProjectState{WdpPath=wdpPath};void Log(string m){st.Log.Add(m);progress?.Invoke(m);}
  st.Wdp=TextFileService.Read(wdpPath);st.Properties=TextFileService.Group(st.Wdp,'?');st.Options=TextFileService.Group(st.Wdp,'+');st.Entries=TextFileService.Drawings(st.Wdp);st.Marker=MarkerService.Read(wdpPath);
  if(st.Properties.Count==0&&st.Options.Count==0)throw new InvalidOperationException("The file has no ?[n] or +[n] lines, so it does not look like an AutoCAD Electrical project: "+wdpPath);
  Log($"Project: {wdpPath} ({st.Wdp.Lines.Count} lines, {TextFileService.EncodingName(st.Wdp.Encoding)}, {st.Properties.Count} properties, {st.Options.Count} options, {st.Entries.Count} drawings)");
  if(st.Marker is not null)Log($"Applied profile on record: {st.Marker.Profile} / {st.Marker.Scheme} on {st.Marker.Applied:yyyy-MM-dd HH:mm} by {st.Marker.By}");
  foreach(var e in st.Entries){string full=TextFileService.FullPath(wdpPath,e);var d=new DrawingState{Path=full,Exists=File.Exists(full)};st.Drawings.Add(d);if(!d.Exists){d.Error="file not found";continue;}
   if(!inspectDrawings||!bridge.CanInspect)continue;Log("Reading "+e.Path);try{var i=bridge.Inspect!(full);d.OpenInEditor=i.OpenInEditor;d.ReadFromEditor=i.ReadFromEditor;d.HasWdm=i.HasWdm;d.WdmValues=i.WdmValues;d.WdmTags=i.WdmTags;d.Error=i.Error;}catch(Exception ex){d.Error=ex.Message;}}
  st.DrawingsInspected=inspectDrawings&&bridge.CanInspect;if(st.DrawingsInspected)Log($"Drawings: {st.Drawings.Count(d=>d.Readable&&d.HasWdm)} with {r.WdmBlockName}, {st.Drawings.Count(d=>d.OpenInEditor)} open in the editor ({st.Drawings.Count(d=>d.ReadFromEditor)} read from the session), {st.Drawings.Count(d=>!d.Exists)} missing on disk");return st;}
 public static FromToSettings? ResolveFromTo(EnvironmentProfile? p,WireScheme? s)=>s is not null?(s.IsFromTo?(p?.FromTo??s.FromTo):null):p?.FromTo;
 public static Dictionary<string,string> Resolve(EnvironmentProfile? p,WireScheme? s,EnvRules r,AppSettings settings,Action<string> log){var v=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
  if(s is not null){if(s.FromTemplate){string t=settings.TemplateProjectPath.Trim();if(t.Length==0||!File.Exists(t))log("Scheme '"+s.Name+"' takes its values from the LSE template, which was not found: "+t+". Set 'Template project (.wdp)' in LSEENVSETTINGS.");
    else{var tpl=TextFileService.Read(t);foreach(string k in s.TemplateKeys){var m=r.Map(k);if(m is null)continue;string? tv=m.Property>=0?TextFileService.Get(tpl,'?',m.Property):m.Option>=0?TextFileService.Get(tpl,'+',m.Option):null;if(tv is null)log("Template has no line for "+k+" ("+m.Where+"); skipped");else v[k]=tv;}log("Scheme '"+s.Name+"': "+v.Count+" value(s) read from "+t);}}
   foreach(var (k,val) in s.Values)v[k]=val;}
  if(p is not null)foreach(var (k,val) in p.Values)v[k]=val;return v;}
 public static EnvPlan Plan(ProjectState st,EnvironmentProfile? p,WireScheme? s,EnvRules r,AppSettings settings,HostBridge bridge,bool applyDrawings,bool fromTo,Action<string>? progress=null){
  var plan=new EnvPlan{Project=st,Profile=p,Scheme=s,Rules=r};void Log(string m){plan.Log.Add(m);progress?.Invoke(m);}
  if(s is null&&p is not null&&p.Scheme.Trim().Length>0){s=r.Scheme(p.Scheme.Trim());plan.Scheme=s;if(s is null)Log("Profile names wire scheme '"+p.Scheme+"', which the rules JSON does not define; only the profile's own values are applied");}
  Log($"Planning for {st.WdpPath}: profile {plan.ProfileName}, wire scheme {plan.SchemeName}");
  plan.Resolved=Resolve(p,s,r,settings,Log);plan.FromTo=ResolveFromTo(p,s);
  foreach(var (key,value) in plan.Resolved){var m=r.Map(key);string src=p is not null&&p.Values.ContainsKey(key)?"profile":"scheme";
   if(m is null){Info(plan,"Settings",key,"","",$"The rules JSON has no setting map entry named '{key}'. Add it or remove it from the {src}.",src);continue;}
   if(!m.Mapped){Info(plan,m.Group,m.Label,"(unknown)",m.Describe(value),"Not mapped yet: set it by hand in Project Properties, then locate it with LSEENVSNAPSHOT and fill in the rules JSON."+(m.Note.Length>0?" "+m.Note:""),src);continue;}
   if(m.Protected){Info(plan,m.Group,m.Label,Current(st,m),m.Describe(value),"Protected in the setting map; a profile's values never change it. Use a raw 'properties' or 'drawing' override in the profile if the customer really needs it.",src);continue;}
   Line(plan,st,m,'?',m.Property,value,src,m.Label);Line(plan,st,m,'+',m.Option,value,src,m.Label);if(applyDrawings&&m.Wdm.Length>0)Wdm(plan,st,r,m.Wdm,value,src,m.Label,m);}
  if(p is not null){foreach(var (k,val) in p.Properties){if(!int.TryParse(k,out int idx)){Info(plan,"Project properties",k,"","",$"'{k}' is not a ?[n] index; raw property keys are numbers.","profile");continue;}Line(plan,st,null,'?',idx,val,"profile override",r.Label('?',idx));}
   foreach(var (k,val) in p.Options){if(!int.TryParse(k,out int idx)){Info(plan,"Project options",k,"","",$"'{k}' is not a +[n] index; raw option keys are numbers.","profile");continue;}Line(plan,st,null,'+',idx,val,"profile override",r.Label('+',idx));}
   if(applyDrawings)foreach(var (tag,val) in p.Drawing)Wdm(plan,st,r,tag,val,"profile override",r.WdmBlockName+" "+tag,null);
   CopyFile(plan,st,p.WdtSource,TextFileService.MappingPath(st.WdpPath),"Title block mapping (.wdt)");CopyFile(plan,st,p.WdlSource,TextFileService.LabelsPath(st.WdpPath),"Description labels (.wdl)");}
  if(!fromTo)Log("Wire tracing: not requested in this run (From/To numbering and un-fixing skipped)");else if(!bridge.CanReadWires)Log("Wire tracing: no drawing reader available (outside AutoCAD)");else if(!st.DrawingsInspected)Log("Wire tracing: drawings were not read; tick 'Read every drawing' and plan again");else if(plan.FromTo is not null)WirePlans(plan,st,r,bridge,Log);else if(s is not null||st.Marker?.FromTo==true)UnfixPlans(plan,st,r,bridge,Log);
  if(plan.Applicable>0)plan.Changes.Add(new Change{Kind=ChangeKind.Marker,Scope="Project",Item=Path.GetFileName(MarkerService.PathFor(st.WdpPath)),Current=st.Marker is null?"(none)":st.Marker.Profile+" / "+st.Marker.Scheme,New=plan.ProfileName+" / "+plan.SchemeName,Target="marker",Note="Records which profile and scheme were applied so LSE_Doctor and the next engineer can see it.",Source="LSE_Env"});
  foreach(var c in plan.Changes)c.Selected=c.Applies&&c.Recommended;Log($"Plan: {plan.Applicable} change(s), {plan.Changes.Count-plan.Applicable} note(s)");return plan;}
 const string OpenText=" (open in the editor: written in the session, not saved)";
 static string OpenSuffix(DrawingState d)=>d.OpenInEditor?OpenText:"";
 static string OpenSuffix(ProjectState st,string path)=>st.Drawings.Any(d=>d.OpenInEditor&&d.Path.Equals(path,StringComparison.OrdinalIgnoreCase))?OpenText:"";
 static string Reason(Change c)=>c.Note.Contains("open in the editor",StringComparison.OrdinalIgnoreCase)?"open in the editor":c.Note.StartsWith("Not mapped",StringComparison.OrdinalIgnoreCase)?"not mapped":c.Current=="(attribute missing)"?"attribute missing":c.Note.Contains("already carries",StringComparison.OrdinalIgnoreCase)?"already carries":c.Note.Contains("already matches",StringComparison.OrdinalIgnoreCase)||c.Note.Contains("already uses",StringComparison.OrdinalIgnoreCase)?"already matches":c.Note.StartsWith("Protected",StringComparison.OrdinalIgnoreCase)?"protected":c.Note.Contains("could not be read",StringComparison.OrdinalIgnoreCase)||c.Note.StartsWith("Not planned",StringComparison.OrdinalIgnoreCase)?"could not be read":c.Note.Contains("has no WD_M",StringComparison.OrdinalIgnoreCase)||c.Note.Contains(" block;",StringComparison.OrdinalIgnoreCase)?"no WD_M block":"other";
 public static string NothingToApply(EnvPlan plan){var notes=plan.Changes.Where(c=>!c.Applies).ToList();if(notes.Count==0)return "Nothing to apply: the profile and scheme produced no changes.";var lines=new List<string>{$"Nothing to apply. {notes.Count} note(s):"};
  foreach(var g in notes.GroupBy(Reason).OrderByDescending(g=>g.Count())){int n=g.Count();lines.Add("  "+n+" "+g.Key switch{"open in the editor"=>"drawing(s) open in the editor could not be read (close them, or check the message in the Note column)","not mapped"=>"setting(s) not mapped yet (set by hand, locate with LSEENVSNAPSHOT, fill in the rules JSON)","attribute missing"=>"drawing(s) lack the WD_M attribute (Project > Other Tools > Update to New WD_M Block)","already carries"=>"drawing(s) already carry the From/To numbers","already matches"=>"item(s) already match","protected"=>"protected setting(s) left alone","could not be read"=>"drawing(s) could not be read or traced","no WD_M block"=>"drawing(s) have no WD_M block (open in AutoCAD Electrical or repair with LSE_Doctor)",_=>"other note(s)"});}
  lines.Add("Each note is listed in the grid (tick 'Show notes') with its reason.");return string.Join(Environment.NewLine,lines);}
 static string Current(ProjectState st,SettingMap m)=>m.Property>=0?st.Property(m.Property)??"(line missing)":m.Option>=0?st.Option(m.Option)??"(line missing)":"";
 static void Info(EnvPlan plan,string scope,string item,string cur,string nw,string note,string src)=>plan.Changes.Add(new Change{Kind=ChangeKind.Info,Scope=scope,Item=item,Current=cur,New=nw,Note=note,Source=src,Selected=false,Recommended=false});
 static void Line(EnvPlan plan,ProjectState st,SettingMap? m,char prefix,int idx,string value,string src,string label){if(idx<0)return;var r=plan.Rules;string scope=prefix=='?'?"Project properties":"Project options";string? cur=prefix=='?'?st.Property(idx):st.Option(idx);
  if(r.IsProtected(prefix,idx)){Info(plan,scope,label,cur??"(line missing)",value,"Protected by the rules JSON (protected"+(prefix=='?'?"Properties":"Options")+"); left alone.",src);return;}
  plan.Changes.RemoveAll(c=>c.Target=="wdp"&&c.Prefix==prefix&&c.Index==idx&&c.Applies);if(cur is not null&&cur.Trim().Equals(value.Trim(),StringComparison.Ordinal))return;
  plan.Changes.Add(new Change{Kind=prefix=='?'?ChangeKind.SetProperty:ChangeKind.SetOption,Scope=scope,Item=label,Current=cur??"(line missing)",New=m?.Describe(value)??value,Target="wdp",Prefix=prefix,Index=idx,Value=value,Source=src,Note=cur is null?"The line is added in index order.":"Project-level value; new drawings inherit it."});}
 static void Wdm(EnvPlan plan,ProjectState st,EnvRules r,string tag,string value,string src,string label,SettingMap? m){const string scope="Drawing settings (WD_M)";
  foreach(var d in st.Drawings){if(!d.Exists)continue;string item=d.Name+" : "+tag;
   if(d.Error.Length>0){Note(plan,scope,d,(d.OpenInEditor?"is open in the editor and could not be read: ":"could not be read: ")+d.Error);continue;}
   if(!st.DrawingsInspected){Note(plan,scope,d,"not read; tick 'Read every drawing' to plan WD_M changes");continue;}
   if(!d.HasWdm){Note(plan,scope,d,"has no "+r.WdmBlockName+" block; open it once in AutoCAD Electrical (or repair it with LSE_Doctor) and plan again");continue;}
   if(!d.Has(tag)){Info(plan,scope,item,"(attribute missing)",value,"This drawing's "+r.WdmBlockName+" is older and has no "+tag+". In AutoCAD Electrical use Project > Other Tools > Update to New WD_M Block, then plan again.",src);continue;}
   string cur=d.Wdm(tag);plan.Changes.RemoveAll(c=>c.Kind==ChangeKind.SetWdm&&c.Target.Equals(d.Path,StringComparison.OrdinalIgnoreCase)&&c.Name.Equals(tag,StringComparison.OrdinalIgnoreCase));if(cur.Trim().Equals(value.Trim(),StringComparison.Ordinal))continue;
   plan.Changes.Add(new Change{Kind=ChangeKind.SetWdm,Scope=scope,Item=item,Current=cur,New=m?.Describe(value)??value,Target=d.Path,Name=tag,Value=value,Source=src,Note=label+". Takes effect the next time wire numbers / tags are inserted or retagged in this drawing."+OpenSuffix(d)});}}
 static void Note(EnvPlan plan,string scope,DrawingState d,string why){string text=d.Name+" "+why+".";if(plan.Changes.Any(c=>c.Kind==ChangeKind.Info&&c.Scope==scope&&c.Note==text))return;Info(plan,scope,d.Name,"","",text,"");}
 static void CopyFile(EnvPlan plan,ProjectState st,string source,string target,string what){source=source.Trim();if(source.Length==0)return;const string scope="Project files";
  if(!File.Exists(source)){Info(plan,scope,what,"","",$"Profile names a source file that does not exist: {source}","profile");return;}string? existing=TextFileService.ExistingCaseInsensitive(target);
  if(existing is not null){try{if(File.ReadAllBytes(existing).AsSpan().SequenceEqual(File.ReadAllBytes(source)))return;}catch{}}
  plan.Changes.Add(new Change{Kind=ChangeKind.CopyFile,Scope=scope,Item=what,Current=existing is null?"(file missing)":Path.GetFileName(existing),New=source,Target=existing??target,Value=source,Source="profile",Recommended=false,Note="Copies the customer's file over the project's. Unticked by default: tick it when the customer's title block or description labels really differ."});}
 static void WirePlans(EnvPlan plan,ProjectState st,EnvRules r,HostBridge bridge,Action<string> log){var f=plan.FromTo!;var plans=new List<WirePlan>();const string scope="Wire numbers (From/To)";
  foreach(var d in st.Drawings){if(!d.Exists)continue;var wp=new WirePlan{Drawing=d.Path};if(d.Error.Length>0){wp.Error=(d.OpenInEditor?"open in the editor and could not be read: ":"")+d.Error;}
   else{log("Tracing wires in "+d.Name);try{var w=bridge.ReadWires!(d.Path);wp.Sheet=w.Sheet;wp.FixedLayer=w.FixedLayer;wp.WireNoLayer=w.WireNoLayer;wp.Networks=WireNetworkService.Build(w,r.FromTo);wp.Notes.AddRange(w.Notes);if(w.UntaggedConnections>0)wp.Notes.Add(w.UntaggedConnections+" connection point(s) belong to symbols without a tag and were ignored");}catch(Exception ex){wp.Error=ex.Message;}}
   plans.Add(wp);}
  WireNetworkService.Assign(plans,f,r.FromTo);
  foreach(var wp in plans){string name=Path.GetFileName(wp.Drawing);if(wp.Error.Length>0){Info(plan,scope,name,"","","Not planned: "+wp.Error+".","scheme");continue;}
   if(wp.HasWork)plan.Changes.Add(new Change{Kind=ChangeKind.WireNumbers,Scope=scope,Item=name,Current=wp.Count(WireAction.Set)+wp.Count(WireAction.Insert)+" network(s) to number",New=wp.Summary,Target=wp.Drawing,Wires=wp,Source="scheme",Note="Writes FROM-TO numbers"+(f.Fixed?" on the fixed wire-number layer ("+wp.FixedLayer+")":"")+". The report lists every network."+OpenSuffix(st,wp.Drawing)});
   else Info(plan,scope,name,"",wp.Summary,wp.Networks.Count==0?"No wires found on the wire layers.":"Every numbered network already carries its From/To number.","scheme");}
  log($"From/To: {plans.Count(p=>p.HasWork)} drawing(s) need wire numbers, {plans.Sum(p=>p.Networks.Count)} network(s) traced");}
 static void UnfixPlans(EnvPlan plan,ProjectState st,EnvRules r,HostBridge bridge,Action<string> log){const string scope="Wire numbers (fixed)";bool recommended=st.Marker?.FromTo==true;int total=0;
  foreach(var d in st.Drawings){if(!d.Exists)continue;if(d.Error.Length>0){Info(plan,scope,d.Name,"","","Not checked for fixed wire numbers: "+(d.OpenInEditor?"open in the editor and could not be read: ":"")+d.Error+".","scheme");continue;}
   DrawingWires w;try{log("Looking for fixed wire numbers in "+d.Name);w=bridge.ReadWires!(d.Path);}catch(Exception ex){Info(plan,scope,d.Name,"","","Not checked for fixed wire numbers: "+ex.Message,"scheme");continue;}
   var fixedMarks=w.Marks.Where(m=>m.IsFixed).ToList();if(fixedMarks.Count==0)continue;total+=fixedMarks.Count;
   plan.Changes.Add(new Change{Kind=ChangeKind.UnfixWireNumbers,Scope=scope,Item=d.Name,Current=fixedMarks.Count+" fixed wire number(s) on "+w.FixedLayer,New="moved to "+w.WireNoLayer+" (normal)",Target=d.Path,Value=w.WireNoLayer,Handles=fixedMarks.Select(m=>m.Handle).ToList(),Source="scheme",Recommended=recommended,
    Note=(recommended?"The project record says From/To numbers were written as fixed; un-fixing lets AutoCAD Electrical's retag renumber them under the new scheme.":"Fixed wire numbers stay as they are during a retag. Unticked because no From/To run is on record for this project; tick it if these were written by LSE_Env or should follow the new scheme.")+OpenSuffix(d)});}
  log($"Fixed wire numbers: {total} found in {plan.Changes.Count(c=>c.Kind==ChangeKind.UnfixWireNumbers)} drawing(s)");}
 public static EnvironmentProfile Capture(ProjectState st,EnvRules r,string name){var p=new EnvironmentProfile{Name=name,CapturedFrom=st.WdpPath,Captured=DateTime.Now,Description="Captured from "+st.ProjectName};
  foreach(var m in r.Settings.Where(x=>x.Mapped&&!x.Protected)){string? v=m.Property>=0?st.Property(m.Property):m.Option>=0?st.Option(m.Option):null;if(v is null&&m.Wdm.Length>0){var d=st.Drawings.FirstOrDefault(x=>x.Readable&&x.Has(m.Wdm));v=d?.Wdm(m.Wdm);}if(v is not null)p.Values[m.Key]=v;}return p;}
 public static Snapshot Take(string wdpPath,EnvRules r,HostBridge bridge,bool drawings){var st=ReadProject(wdpPath,r,bridge,drawings);var s=new Snapshot{WdpPath=st.WdpPath};
  foreach(var (i,v) in st.Properties)s.Wdp["?["+i+"]"]=v;foreach(var (i,v) in st.Options)s.Wdp["+["+i+"]"]=v;foreach(var l in st.Wdp.Lines.Where(l=>l.StartsWith("*[",StringComparison.Ordinal)))if(TextFileService.TryIndexed(l,'*',out int i,out string v))s.Wdp["*["+i+"]"]=v;
  foreach(var d in st.Drawings){if(!d.Readable||!d.HasWdm){if(drawings)s.Notes.Add(d.Name+": "+(d.Error.Length>0?(d.OpenInEditor?"open in the editor and could not be read: ":"")+d.Error:"no WD_M"));continue;}s.Drawings[d.Path]=new(d.WdmValues,StringComparer.OrdinalIgnoreCase);}return s;}
 public static List<string> Diff(Snapshot a,Snapshot b,EnvRules r){var x=new List<string>();
  foreach(string k in a.Wdp.Keys.Union(b.Wdp.Keys).OrderBy(k=>k[0]).ThenBy(k=>int.TryParse(k[2..k.IndexOf(']')],out int n)?n:0)){a.Wdp.TryGetValue(k,out var va);b.Wdp.TryGetValue(k,out var vb);if(va==vb)continue;var m=r.MapFor(k[0],int.Parse(k[2..k.IndexOf(']')]));x.Add($"wdp {k}{(m is not null?" ("+m.Key+")":"")}: \"{va??"(missing)"}\" -> \"{vb??"(missing)"}\"");}
  foreach(string d in a.Drawings.Keys.Union(b.Drawings.Keys,StringComparer.OrdinalIgnoreCase).OrderBy(k=>k,StringComparer.OrdinalIgnoreCase)){a.Drawings.TryGetValue(d,out var da);b.Drawings.TryGetValue(d,out var db);if(da is null||db is null){x.Add(Path.GetFileName(d)+": "+(da is null?"only in B":"only in A"));continue;}
   foreach(string t in da.Keys.Union(db.Keys,StringComparer.OrdinalIgnoreCase).OrderBy(k=>k,StringComparer.OrdinalIgnoreCase)){da.TryGetValue(t,out var va);db.TryGetValue(t,out var vb);if(va==vb)continue;var m=r.MapForWdm(t);x.Add($"{Path.GetFileName(d)} WD_M {t}{(m is not null?" ("+m.Key+")":"")}: \"{va??"(missing)"}\" -> \"{vb??"(missing)"}\"");}}
  if(x.Count==0)x.Add("No differences.");return x;}
 public static string Render(EnvPlan plan){var x=new List<string>{"LSE_Env plan","Project: "+plan.Project.WdpPath,"Planned: "+plan.Planned.ToString("s")+" by "+Environment.UserName,"Profile: "+plan.ProfileName+(plan.Profile is not null&&plan.Profile.Customer.Length>0?" ("+plan.Profile.Customer+")":""),"Wire scheme: "+plan.SchemeName+(plan.FromTo is not null?" [From/To "+plan.FromTo.Format+"]":""),"Rules: "+plan.Rules.Source,$"Changes: {plan.Applicable} ({plan.Selected} ticked), notes: {plan.Changes.Count-plan.Applicable}",""};
  foreach(var g in plan.Changes.GroupBy(c=>c.Scope)){x.Add("== "+g.Key);foreach(var c in g){x.Add($"  [{(c.Applies?(c.Selected?"x":" "):"i")}] {c.Item}: {Short(c.Current)}  ->  {Short(c.New)}  |  {c.KindText}{(c.Source.Length>0?" ("+c.Source+")":"")}{(c.Note.Length>0?"  |  "+c.Note:"")}");if(c.Wires is not null)x.Add(WireNetworkService.Render(c.Wires));}x.Add("");}
  x.Add("== Log");x.AddRange(plan.Project.Log.Concat(plan.Log).Select(l=>"  "+l));return string.Join(Environment.NewLine,x);}
 public static string Short(string v,int max=160){v=v.Replace("\r"," ").Replace("\n"," ");return v.Length<=max?v:v[..max]+"...";}
}
